function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'StockPrice' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with StockPrice and no arguments.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls in total.';
  const inRange = (v) => Number.isInteger(v) && v >= 1 && v <= 1000000000;
  let updated = false;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'update') {
      if (a.length !== 2 || !inRange(a[0]) || !inRange(a[1])) return 'update takes a timestamp and a price, each from 1 to 10^9.';
      updated = true;
    } else if (operations[i] === 'current' || operations[i] === 'maximum' || operations[i] === 'minimum') {
      if (a.length !== 0) return 'current, maximum and minimum take no arguments.';
      if (!updated) return 'current, maximum and minimum need at least one update first.';
    } else {
      return 'Only update, current, maximum and minimum can follow the constructor.';
    }
  }
  return null;
}

