class StockPrice {
  constructor() {
    this.prices = new Map();
    this.latest = 0;
    this.minHeap = [];
    this.maxHeap = [];
  }

  update(timestamp, price) {
    this.prices.set(timestamp, price);
    this.latest = Math.max(this.latest, timestamp);
    this.push(this.minHeap, [price, timestamp]);
    this.push(this.maxHeap, [-price, timestamp]);
  }

  current() {
    return this.prices.get(this.latest);
  }

  maximum() {
    return this.top(this.maxHeap, -1);
  }

  minimum() {
    return this.top(this.minHeap, 1);
  }

  top(heap, sign) {
    while (this.prices.get(heap[0][1]) !== sign * heap[0][0]) {
      this.pop(heap);
    }
    return sign * heap[0][0];
  }

  push(heap, entry) {
    heap.push(entry);
    let index = heap.length - 1;
    while (index > 0) {
      const parent = (index - 1) >> 1;
      if (heap[parent][0] <= heap[index][0]) break;
      [heap[parent], heap[index]] = [heap[index], heap[parent]];
      index = parent;
    }
  }

  pop(heap) {
    const last = heap.pop();
    if (heap.length === 0) return;
    heap[0] = last;
    let index = 0;
    for (;;) {
      const left = 2 * index + 1;
      const right = left + 1;
      let smallest = index;
      if (left < heap.length && heap[left][0] < heap[smallest][0]) smallest = left;
      if (right < heap.length && heap[right][0] < heap[smallest][0]) smallest = right;
      if (smallest === index) return;
      [heap[smallest], heap[index]] = [heap[index], heap[smallest]];
      index = smallest;
    }
  }
}

