class StockPrice {
  constructor() {
    this.records = {};
  }
  update(timestamp, price) {
    this.records[timestamp] = price;
  }
  current() {
    const times = Object.keys(this.records).map(Number);
    let last = times[0];
    for (const t of times) if (t > last) last = t;
    return this.records[last];
  }
  maximum() {
    let best = -Infinity;
    for (const p of Object.values(this.records)) if (p > best) best = p;
    return best;
  }
  minimum() {
    let best = Infinity;
    for (const p of Object.values(this.records)) if (p < best) best = p;
    return best;
  }
}

