function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const calls = large ? 499 : int(1, 15);
  const timeTop = large ? (rand() < 0.5 ? 300 : 1000000000) : int(1, 6);
  const priceTop = large ? (rand() < 0.5 ? 50 : 1000000000) : (rand() < 0.7 ? 10 : 1000000000);
  const updateRate = 0.3 + rand() * 0.4;
  const queries = ['current', 'maximum', 'minimum'];
  const operations = ['StockPrice'];
  const args = [[]];
  for (let i = 0; i < calls; i++) {
    if (i === 0 || rand() < updateRate) {
      operations.push('update');
      args.push([int(1, timeTop), int(1, priceTop)]);
    } else {
      operations.push(queries[int(0, 2)]);
      args.push([]);
    }
  }
  return [operations, args];
}
